create type public.major_incident_status as enum ('DECLARED','MITIGATING','RESOLVED','CLOSED');
create sequence public.major_incident_number_sequence start 1;
create or replace function public.next_major_incident_number() returns text language plpgsql volatile set search_path=public as $$ begin return format('MI-%s-%s',to_char(current_date,'YYYY'),lpad(nextval('public.major_incident_number_sequence')::text,6,'0')); end; $$;
create table public.major_incidents(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,incident_number text not null unique default public.next_major_incident_number(),ticket_id uuid not null unique references public.tickets(id) on delete restrict,status public.major_incident_status not null default 'DECLARED',impact_summary text not null check(length(trim(impact_summary)) between 10 and 10000),resolution_summary text,declared_by uuid not null references public.user_profiles(id) on delete restrict,declared_at timestamptz not null default clock_timestamp(),resolved_at timestamptz,closed_at timestamptz,closed_by uuid references public.user_profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(resolution_summary is null or length(trim(resolution_summary)) between 10 and 10000)
);
create table public.major_incident_communications(
 id uuid primary key default gen_random_uuid(),major_incident_id uuid not null references public.major_incidents(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,audience text not null check(audience in ('INTERNAL','CUSTOMER','EXECUTIVE')),message text not null check(length(trim(message)) between 10 and 10000),communicated_by uuid not null references public.user_profiles(id) on delete restrict,communicated_at timestamptz not null default clock_timestamp()
);
create index major_incidents_org_status_idx on public.major_incidents(organization_id,status,declared_at desc); create index major_incident_communications_incident_idx on public.major_incident_communications(major_incident_id,communicated_at);
create trigger major_incidents_updated before update on public.major_incidents for each row execute function public.set_updated_at();
alter table public.major_incidents enable row level security; alter table public.major_incident_communications enable row level security;
create policy "governance reads major incidents" on public.major_incidents for select to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','DISPATCHER','AUDITOR']::public.platform_role[]));
create policy "governance reads major incident communications" on public.major_incident_communications for select to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','DISPATCHER','AUDITOR']::public.platform_role[]));
create or replace function public.declare_major_incident(target_ticket_id uuid,target_impact_summary text)
returns uuid language plpgsql security definer set search_path=public as $$ declare ticket public.tickets%rowtype; incident_id uuid;
begin select * into ticket from public.tickets where id=target_ticket_id for update; if ticket.id is null or not public.has_organization_role(ticket.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','DISPATCHER']::public.platform_role[]) then raise exception 'MAJOR_INCIDENT_NOT_AUTHORIZED'; end if; if ticket.ticket_type<>'INCIDENT' then raise exception 'MAJOR_INCIDENT_TICKET_TYPE_REQUIRED'; end if; if coalesce(length(trim(target_impact_summary)),0) not between 10 and 10000 then raise exception 'MAJOR_INCIDENT_INVALID_INPUT'; end if;
insert into public.major_incidents(organization_id,ticket_id,impact_summary,declared_by) values(ticket.organization_id,ticket.id,trim(target_impact_summary),auth.uid()) returning id into incident_id;
insert into public.entity_relationships(organization_id,source_entity_type,source_entity_id,target_entity_type,target_entity_id,relationship_type,reason,created_by) values(ticket.organization_id,'TICKET',ticket.id,'MAJOR_INCIDENT',incident_id,'ESCALATED_TO','Incidente maior declarado.',auth.uid());
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(ticket.organization_id,auth.uid(),'MAJOR_INCIDENT_DECLARED','major_incident',incident_id,jsonb_build_object('ticket_id',ticket.id),'WEB'); return incident_id; end; $$;
create or replace function public.add_major_incident_communication(target_incident_id uuid,target_audience text,target_message text)
returns uuid language plpgsql security definer set search_path=public as $$ declare incident public.major_incidents%rowtype; communication_id uuid;
begin select * into incident from public.major_incidents where id=target_incident_id for update; if incident.id is null or not public.has_organization_role(incident.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','DISPATCHER']::public.platform_role[]) then raise exception 'MAJOR_INCIDENT_NOT_AUTHORIZED'; end if; if incident.status in('RESOLVED','CLOSED') then raise exception 'MAJOR_INCIDENT_NOT_ACTIVE'; end if; if target_audience not in('INTERNAL','CUSTOMER','EXECUTIVE') or coalesce(length(trim(target_message)),0) not between 10 and 10000 then raise exception 'MAJOR_INCIDENT_COMMUNICATION_INVALID'; end if;
insert into public.major_incident_communications(major_incident_id,organization_id,audience,message,communicated_by) values(incident.id,incident.organization_id,target_audience,trim(target_message),auth.uid()) returning id into communication_id; update public.major_incidents set status='MITIGATING' where id=incident.id and status='DECLARED';
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(incident.organization_id,auth.uid(),'MAJOR_INCIDENT_COMMUNICATION_RECORDED','major_incident_communication',communication_id,jsonb_build_object('major_incident_id',incident.id,'audience',target_audience),'WEB'); return communication_id; end; $$;
create or replace function public.update_major_incident_status(target_incident_id uuid,target_status public.major_incident_status,target_resolution_summary text default null)
returns void language plpgsql security definer set search_path=public as $$ declare incident public.major_incidents%rowtype;
begin select * into incident from public.major_incidents where id=target_incident_id for update; if incident.id is null or not public.has_organization_role(incident.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','DISPATCHER']::public.platform_role[]) then raise exception 'MAJOR_INCIDENT_NOT_AUTHORIZED'; end if; if (incident.status='DECLARED' and target_status<>'MITIGATING') or (incident.status='MITIGATING' and target_status<>'RESOLVED') or (incident.status='RESOLVED' and target_status<>'CLOSED') or incident.status='CLOSED' then raise exception 'MAJOR_INCIDENT_INVALID_TRANSITION'; end if; if target_status in('RESOLVED','CLOSED') and coalesce(length(trim(target_resolution_summary)),0) not between 10 and 10000 then raise exception 'MAJOR_INCIDENT_RESOLUTION_REQUIRED'; end if;
update public.major_incidents set status=target_status,resolution_summary=case when target_status in('RESOLVED','CLOSED') then trim(target_resolution_summary) else resolution_summary end,resolved_at=case when target_status='RESOLVED' then clock_timestamp() else resolved_at end,closed_at=case when target_status='CLOSED' then clock_timestamp() else closed_at end,closed_by=case when target_status='CLOSED' then auth.uid() else closed_by end where id=incident.id;
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(incident.organization_id,auth.uid(),'MAJOR_INCIDENT_STATUS_CHANGED','major_incident',incident.id,jsonb_build_object('status',target_status),'WEB'); end; $$;
revoke all on function public.declare_major_incident(uuid,text) from public; revoke all on function public.add_major_incident_communication(uuid,text,text) from public; revoke all on function public.update_major_incident_status(uuid,public.major_incident_status,text) from public;
grant execute on function public.declare_major_incident(uuid,text) to authenticated; grant execute on function public.add_major_incident_communication(uuid,text,text) to authenticated; grant execute on function public.update_major_incident_status(uuid,public.major_incident_status,text) to authenticated;
